/**
 * Augments the OpenNext-generated `CloudflareEnv` with the bindings and
 * secrets chowdown adds. `worker-configuration.d.ts` (regenerated by
 * `wrangler types`) already declares the `DB` D1 binding; the string members
 * here are the Worker secrets we set from `.dev.vars` locally and via
 * `wrangler secret put` in production. Declaration-merging them onto
 * `CloudflareEnv` means `getCloudflareContext().env` is fully typed everywhere.
 */
declare global {
  interface CloudflareEnv {
    /** D1 database binding (declared in worker-configuration.d.ts too). */
    DB: D1Database;
    /** Workers AI binding — recipe-content → Cooklang conversion. */
    AI: Ai;
    /** OAuth web client id for the chowdown-mridang project. */
    GOOGLE_OAUTH_CLIENT_ID: string;
    /** OAuth web client secret (server-side only). */
    GOOGLE_OAUTH_CLIENT_SECRET: string;
    /** GCP project id, `chowdown-mridang`. */
    GOOGLE_PROJECT_ID: string;
    /** Service-account email used for folder-wide reads/writes. */
    GOOGLE_SERVICE_ACCOUNT_EMAIL: string;
    /** Base64 of the service-account JSON key. */
    GOOGLE_SERVICE_ACCOUNT_KEY_B64: string;
    /** 256-bit base64 key that seals stored refresh tokens (see lib/crypto). */
    TOKEN_ENCRYPTION_KEY: string;
    /** Secret that signs the session cookie. */
    SESSION_SECRET: string;
    /** Public origin, e.g. https://chowdown.apps.mrida.ng. Optional; derived
     * from the request when unset (local dev). */
    APP_URL?: string;
  }
}

export {};
